spec.setup_code:
var ink='#04204B', sec='#3D5F91', guide='#8098BC';
var BL=[11,79,192], WM=[180,85,47], NE=[61,95,145], GR=[128,152,188];
function rng(seed){var s=seed>>>0;return function(){s=(s*1664525+1013904223)>>>0;return s/4294967296;};}
function clamp(x,a,b){return x<a?a:(x>b?b:x);}
function seg(t,a,b){return clamp((t-a)/(b-a),0,1);}
function ez(x){return x*x*(3-2*x);}
function lerp(a,b,t){return a+(b-a)*t;}
function mixc(a,b,t){return [lerp(a[0],b[0],t),lerp(a[1],b[1],t),lerp(a[2],b[2],t)];}
function rgba(c,a){return 'rgba('+Math.round(c[0])+','+Math.round(c[1])+','+Math.round(c[2])+','+clamp(a,0,1).toFixed(3)+')';}
function ecol(e){return mixc(BL,WM,clamp(e*1.15,0,1));}
function txt(c,s,x,y,col,al,size){c.font=(size||12)+'px sans-serif';c.textAlign=al||'left';c.fillStyle=col;c.fillText(s,x,y);}
function rr(c,x,y,w,h,r){c.beginPath();c.moveTo(x+r,y);c.arcTo(x+w,y,x+w,y+h,r);c.arcTo(x+w,y+h,x,y+h,r);c.arcTo(x,y+h,x,y,r);c.arcTo(x,y,x+w,y,r);c.closePath();}
function arrow(c,x1,y1,x2,y2,col,dash,off){
  c.strokeStyle=col;c.fillStyle=col;c.lineWidth=1.5;c.setLineDash(dash||[]);c.lineDashOffset=off||0;
  c.beginPath();c.moveTo(x1,y1);c.lineTo(x2,y2);c.stroke();c.setLineDash([]);
  var a=Math.atan2(y2-y1,x2-x1);
  c.beginPath();c.moveTo(x2,y2);c.lineTo(x2-7*Math.cos(a-0.4),y2-7*Math.sin(a-0.4));c.lineTo(x2-7*Math.cos(a+0.4),y2-7*Math.sin(a+0.4));c.closePath();c.fill();
}
var N=16, R=rng(11);
var err=[0.1,0.12,0.2,0.15,0.1,0.25,0.5,0.8,0.9,0.7,0.4,0.2,0.3,0.55,0.6,0.35];
var ang=[],nu=[],nv=[],init=[],tgtL=[],initP=[],tgtP=[];
for(var i=0;i<N;i++){ang.push(R()*6.283);nu.push(0.05+0.9*R());nv.push(0.05+0.9*R());init.push(0.25+0.6*R());tgtL.push(1-0.9*err[i]);}
for(var a=0;a<N;a++){for(var b=0;b<N;b++){initP.push(R());tgtP.push(clamp(0.45*(err[a]+err[b])+0.1*Math.abs(a-b)/15,0,1));}}
var caps=['1 · Mini-rollout: noise → structure (no gradients)','2 · Compare to ground truth → error targets','3 · Confidence head learns to match the errors'];

return {draw:function(c,W,H,time,dt){
  c.setLineDash([]);c.globalAlpha=1;c.fillStyle='#ffffff';c.fillRect(0,0,W,H);
  var T=time%14, fade=Math.min(seg(T,0,0.5),1-seg(T,13.4,14));
  var ph=T<5.6?0:(T<9?1:2), ps=[0,5.6,9][ph];
  // caption
  var capA=Math.min(ph==0?seg(T,0,0.5):seg(T,ps,ps+0.4),1-seg(T,13.4,14));
  var fs=12;c.font=fs+'px sans-serif';
  while(c.measureText(caps[ph]).width>W-16&&fs>11){fs--;c.font=fs+'px sans-serif';}
  c.globalAlpha=capA;txt(c,caps[ph],W/2,22,ink,'center',fs);
  // geometry
  var pad=10,u=W-2*pad,pillW=clamp(0.17*u,50,90),panelX=pad+pillW+14,panelW=W-pad-panelX;
  var panelY=0.10*H,panelH=0.33*H,yB=0.555*H,maxH=0.075*H;
  var boxTop=0.68*H,boxBot=0.975*H,boxH=boxBot-boxTop,boxX=pad,boxW=0.30*u;
  var pLx=pad+0.38*u,pLw=0.30*u,oX=pLx-7,oW=W-pad-oX;
  var paeW=0.28*u,paeX=pad+0.72*u;
  var cw=Math.min(panelW-24,panelH*2.6),cx0=panelX+(panelW-cw)/2,cy0=panelY+34,ch=panelH-46;
  // pill
  var pillY=panelY+panelH*0.12,pillH=panelH*0.76,pcx=pillX0(),pulse=0.5+0.5*Math.sin(time*3);
  function pillX0(){return pad+pillW/2;}
  c.globalAlpha=1;
  rr(c,pad,pillY,pillW,pillH,pillW/2.4);c.fillStyle=rgba(BL,0.08+0.08*pulse*(ph==0?1:0));c.fill();c.strokeStyle=rgba(BL,1);c.lineWidth=1.5;c.stroke();
  txt(c,'trunk',pcx,pillY+pillH/2-14,sec,'center',11);
  txt(c,'c =',pcx,pillY+pillH/2+2,ink,'center',12);
  txt(c,'(s, z)',pcx,pillY+pillH/2+18,ink,'center',12);
  c.globalAlpha=fade;
  if(ph==0){c.globalAlpha=fade*(0.5+0.5*pulse);arrow(c,pad+pillW+2,pillY+pillH/2,panelX-2,pillY+pillH/2,rgba(BL,1));}
  // panel
  c.globalAlpha=fade*0.7;rr(c,panelX,panelY,panelW,panelH,8);c.strokeStyle=guide;c.lineWidth=1;c.stroke();
  // chain positions
  var pos=[],pr=[],tr=[];
  var kf=seg(T,0.6,5.0),sp=ez(kf),k=Math.min(20,1+Math.floor(kf*20));
  for(var i=0;i<N;i++){
    var v=0.5+0.3*Math.sin(i*0.6+0.4)+0.14*Math.sin(i*1.5);
    tr[i]=[cx0+(0.03+0.94*i/15)*cw,cy0+v*ch];
    var px=tr[i][0]+Math.cos(ang[i])*err[i]*0.08*cw,py=clamp(tr[i][1]+Math.sin(ang[i])*err[i]*0.08*cw,cy0-6,cy0+ch+6);
    pr[i]=[px,py];
    var m=Math.pow(1-sp,1.6),wb=(1-sp)*3;
    pos[i]=[px+(cx0+nu[i]*cw-px)*m+Math.sin(time*7+i*1.9)*wb,py+(cy0+nv[i]*ch-py)*m+Math.cos(time*6+i*2.3)*wb];
  }
  var br=clamp(cw/55,3.2,5);
  // ground truth (faint grey)
  var tA=ez(seg(T,5.6,6.4));
  if(tA>0){
    c.globalAlpha=fade*tA*0.5;c.strokeStyle=guide;c.lineWidth=3;c.beginPath();
    for(i=0;i<N;i++){if(i==0)c.moveTo(tr[i][0],tr[i][1]);else c.lineTo(tr[i][0],tr[i][1]);}
    c.stroke();c.fillStyle=guide;
    for(i=0;i<N;i++){c.beginPath();c.arc(tr[i][0],tr[i][1],br,0,6.283);c.fill();}
  }
  // error connectors
  var cm=ez(seg(T,6.0,7.0));
  if(cm>0){
    c.lineWidth=1.5;
    for(i=0;i<N;i++){var g=ez(seg(T,6.2+i*0.08,7.2+i*0.08));c.globalAlpha=fade*0.6*g;c.strokeStyle=rgba(ecol(err[i]),1);
      c.beginPath();c.moveTo(tr[i][0],tr[i][1]);c.lineTo(tr[i][0]+(pos[i][0]-tr[i][0])*g,tr[i][1]+(pos[i][1]-tr[i][1])*g);c.stroke();}
  }
  // predicted chain
  c.globalAlpha=fade*0.75;c.strokeStyle=rgba(NE,1);c.lineWidth=1.5;c.beginPath();
  for(i=0;i<N;i++){if(i==0)c.moveTo(pos[i][0],pos[i][1]);else c.lineTo(pos[i][0],pos[i][1]);}
  c.stroke();
  c.globalAlpha=fade;
  for(i=0;i<N;i++){c.fillStyle=rgba(mixc(NE,ecol(err[i]),cm),1);c.beginPath();c.arc(pos[i][0],pos[i][1],br,0,6.283);c.fill();c.strokeStyle='#ffffff';c.lineWidth=1;c.stroke();}
  // top row of panel
  var a0=fade*(1-seg(T,5.4,6.0));
  if(a0>0){
    c.globalAlpha=a0;
    rr(c,panelX+8,panelY+6,Math.min(112,panelW*0.45),18,5);c.fillStyle=rgba(WM,0.12);c.fill();
    txt(c,'∅∇ stop-gradient',panelX+14,panelY+19,WM[0]?'#B4552F':ink,'left',11);
    txt(c,'step '+k+' / 20',panelX+panelW-10,panelY+19,ink,'right',12);
    c.fillStyle=rgba(GR,0.35);c.fillRect(panelX+10,panelY+27,panelW-20,3);
    c.fillStyle=rgba(BL,1);c.fillRect(panelX+10,panelY+27,(panelW-20)*kf,3);
  }
  var a1=fade*ez(seg(T,5.8,6.4));
  if(a1>0){
    c.globalAlpha=a1;
    txt(c,'grey: ground truth',panelX+10,panelY+19,sec,'left',11);
    txt(c,'colour: error',panelX+panelW-10,panelY+19,sec,'right',11);
  }
  // error bars
  if(ph>=1){
    var bw=cw/N*0.62;
    c.globalAlpha=fade*a1;c.strokeStyle=guide;c.lineWidth=1;c.beginPath();c.moveTo(cx0,yB+0.5);c.lineTo(cx0+cw,yB+0.5);c.stroke();
    txt(c,'per-residue error',cx0,yB-maxH-3,sec,'left',11);
    for(i=0;i<N;i++){var gg=ez(seg(T,6.2+i*0.08,7.2+i*0.08));
      c.globalAlpha=fade*gg;c.fillStyle=rgba(ecol(err[i]),1);var bh=err[i]*maxH*gg;c.fillRect(tr[i][0]-bw/2,yB-bh,bw,bh);}
    var tx=fade*ez(seg(T,7.8,8.4))*(1-ez(seg(T,9.2,9.8)));
    if(tx>0){
      c.globalAlpha=tx;var full='targets: lDDT per atom, aligned error per pair';c.font='12px sans-serif';
      if(c.measureText(full).width<panelW-10){txt(c,full,panelX+panelW/2,0.60*H,ink,'center',12);}
      else{txt(c,'targets: lDDT per atom,',panelX+panelW/2,0.60*H,ink,'center',12);txt(c,'aligned error per pair',panelX+panelW/2,0.60*H+14,ink,'center',12);}
    }
  }
  // row B: confidence head
  var a3=ez(seg(T,9.0,9.8)),rowA=fade*(0.25+0.75*a3);
  c.globalAlpha=rowA;
  rr(c,boxX,boxTop,boxW,boxH,8);c.fillStyle=rgba(BL,0.05+0.07*a3);c.fill();c.strokeStyle=rgba(BL,1);c.lineWidth=1.5;c.stroke();
  txt(c,'Pairformer,',boxX+boxW/2,boxTop+16,ink,'center',12);
  txt(c,'4 blocks',boxX+boxW/2,boxTop+30,ink,'center',12);
  var bkH=Math.max(10,(boxH-48)/4-4);
  for(var b=0;b<4;b++){
    var lit=ez(seg(T,9.6+b*0.35,10.0+b*0.35));
    rr(c,boxX+10,boxTop+38+b*(bkH+4),boxW-20,bkH,3);c.fillStyle=rgba(BL,0.1+0.6*lit);c.fill();c.strokeStyle=rgba(BL,0.5);c.lineWidth=1;c.stroke();
  }
  c.globalAlpha=rowA*0.7;rr(c,oX,boxTop,oW,boxH,8);c.setLineDash([4,3]);c.strokeStyle=guide;c.lineWidth=1;c.stroke();c.setLineDash([]);
  c.globalAlpha=fade*a3;
  arrow(c,boxX+boxW+1,boxTop+boxH/2,oX-1,boxTop+boxH/2,rgba(BL,1));
  // inputs to head
  var off=-time*30;
  arrow(c,pcx,pillY+pillH+2,pcx,boxTop-1,rgba(BL,1),[5,3],off);
  txt(c,'s, z',pcx+5,0.655*H,sec,'left',11);
  var dx=boxX+boxW*0.78;
  arrow(c,dx,yB+6,dx,boxTop-1,rgba(NE,1),[5,3],off);
  txt(c,'dist(x̂)',dx+5,0.655*H,sec,'left',11);
  // outputs
  var aO=fade*ez(seg(T,9.8,10.4)),cv=ez(seg(T,10.4,12.8));
  var bY=boxBot-20,bMax=boxH-44,bwid=pLw/N*0.72,lossP=0,lossA=0;
  c.globalAlpha=fade*a3;
  txt(c,'pLDDT',pLx+pLw/2,boxTop+15,ink,'center',12);
  txt(c,'PAE (i × j)',paeX+paeW/2,boxTop+15,ink,'center',12);
  if(aO>0){
    c.globalAlpha=aO;txt(c,'tick = lDDT',pLx+pLw/2,boxBot-5,sec,'center',11);txt(c,'aligned error',paeX+paeW/2,boxBot-5,sec,'center',11);
    for(i=0;i<N;i++){
      var vv=lerp(init[i],tgtL[i],cv)+(1-cv)*0.06*Math.sin(time*5+i);lossP+=Math.abs(vv-tgtL[i])/N;
      var bx=pLx+(i+0.5)*pLw/N-bwid/2,bh2=clamp(vv,0,1)*bMax;
      c.globalAlpha=aO;c.fillStyle=rgba(ecol(1-vv),0.9);c.fillRect(bx,bY-bh2,bwid,bh2);
      c.fillStyle=ink;c.fillRect(bx-1,bY-tgtL[i]*bMax-1,bwid+2,2);
    }
    var cs=Math.min(paeW,bMax+8)/N,sx=paeX+(paeW-cs*N)/2,sy=boxTop+22;
    for(var p=0;p<N;p++){for(var q=0;q<N;q++){
      var pv=lerp(initP[p*N+q],tgtP[p*N+q],cv);lossA+=Math.abs(pv-tgtP[p*N+q])/(N*N);
      c.fillStyle=rgba(ecol(pv),0.9);c.fillRect(sx+q*cs,sy+p*cs,cs+0.5,cs+0.5);
    }}
    c.globalAlpha=aO*0.8;c.strokeStyle=guide;c.lineWidth=1;c.strokeRect(sx,sy,cs*N,cs*N);
    // match arrows
    var mA=fade*ez(seg(T,10.0,10.6)),x1=pLx+pLw/2,x2=paeX+paeW/2;
    c.globalAlpha=mA;
    arrow(c,x1,yB+6,x1,boxTop-2,rgba(WM,1),[5,3],off);
    arrow(c,x2,yB+6,x2,boxTop-2,rgba(WM,1),[5,3],off);
    txt(c,'match targets',(x1+x2)/2,0.625*H,WM[0]?'#B4552F':ink,'center',11);
    txt(c,'loss = '+((lossP+lossA)/2).toFixed(2),(x1+x2)/2,0.625*H+14,ink,'center',11);
  }
  c.globalAlpha=1;
}};
